import{_ as e,o as a,c as i,ae as r}from"./chunks/framework.Czhw_PXq.js";const g=JSON.parse('{"title":"🛠 Best Practices & Quality Standards - TenderCheck AI","description":"","frontmatter":{},"headers":[],"relativePath":"standards/coding_best_practices.md","filePath":"standards/coding_best_practices.md"}'),s={name:"standards/coding_best_practices.md"};function n(c,t,o,l,d,u){return a(),i("div",null,[...t[0]||(t[0]=[r('<h1 id="🛠-best-practices-quality-standards-tendercheck-ai" tabindex="-1">🛠 Best Practices &amp; Quality Standards - TenderCheck AI <a class="header-anchor" href="#🛠-best-practices-quality-standards-tendercheck-ai" aria-label="Permalink to &quot;🛠 Best Practices &amp; Quality Standards - TenderCheck AI&quot;">​</a></h1><h2 id="_1-architecture-design" tabindex="-1">1. Architecture &amp; Design <a class="header-anchor" href="#_1-architecture-design" aria-label="Permalink to &quot;1. Architecture &amp; Design&quot;">​</a></h2><ul><li>[cite_start]<strong>Hexagonal Architecture</strong>: Keep the Domain Layer isolated from Infrastructure (AI, PDF Parsers, DB)[cite: 77, 1096].</li><li>[cite_start]<strong>SOLID Principles</strong>: Each class/function must have a single responsibility[cite: 1253, 1256].</li><li><strong>ADR Management</strong>: Every major architectural decision must be documented in <code>docs/adr/</code> before implementation.</li></ul><h2 id="_2-coding-standards" tabindex="-1">2. Coding Standards <a class="header-anchor" href="#_2-coding-standards" aria-label="Permalink to &quot;2. Coding Standards&quot;">​</a></h2><ul><li>[cite_start]<strong>Strong Typing</strong>: Use TypeScript interfaces/enums for all domain concepts[cite: 72, 214].</li><li>[cite_start]<strong>Validation</strong>: Use Zod for all external data (API inputs, PDF metadata)[cite: 667, 126].</li><li>[cite_start]<strong>Error Handling</strong>: Use custom Error classes and avoid generic try/catch without logging[cite: 128, 494].</li></ul><h2 id="_3-quality-security" tabindex="-1">3. Quality &amp; Security <a class="header-anchor" href="#_3-quality-security" aria-label="Permalink to &quot;3. Quality &amp; Security&quot;">​</a></h2><ul><li>[cite_start]<strong>TDD/Testing</strong>: Minimum 80% code coverage using Vitest[cite: 200, 657].</li><li>[cite_start]<strong>Security</strong>: Implement Helmet.js and follow OWASP Top 10 for LLM applications[cite: 215, 668].</li><li>[cite_start]<strong>Docs as Code</strong>: Documentation (README, ADRs, Mermaid diagrams) must live in the repo[cite: 671, 708].</li></ul><h2 id="_4-ai-interaction-human-in-the-loop" tabindex="-1">4. AI Interaction (Human-in-the-loop) <a class="header-anchor" href="#_4-ai-interaction-human-in-the-loop" aria-label="Permalink to &quot;4. AI Interaction (Human-in-the-loop)&quot;">​</a></h2><ul><li>[cite_start]<strong>Traceability</strong>: All AI-generated responses must include source excerpts and explanations[cite: 70, 1400].</li><li>[cite_start]<strong>Responsible AI</strong>: The system acts as an assistant; the human user always makes the final call[cite: 1223, 1533].</li></ul>',9)])])}const m=e(s,[["render",n]]);export{g as __pageData,m as default};
